def archive_outputs(workspace,paths,destination,build_id):
    root=Path(workspace).resolve();destination=Path(destination)
    if not isinstance(build_id,str) or not re.fullmatch(r'[a-z0-9_-]{1,40}',build_id) or not isinstance(paths,list) or not paths:raise ValueError('build identity and explicit paths')
    if destination.resolve().is_relative_to(root):raise ValueError('archive must outlive workspace')
    if destination.exists():raise FileExistsError(destination)
    data={}
    for name in paths:
        if not isinstance(name,str) or not name or '\\' in name or ':' in name or any(part in ('','.','..') for part in name.split('/')):raise ValueError('relative artifact path')
        parts=PurePosixPath(name)
        if parts.is_absolute() or name in data:raise ValueError('absolute or duplicate artifact')
        source=root
        for part in parts.parts:
            source=source/part
            if source.is_symlink():raise ValueError('symlink artifact')
        if not source.is_file():raise ValueError('regular artifact required')
        data[name]=source.read_bytes()
    manifest={'build_id':build_id,'files':[{'path':name,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()} for name,raw in sorted(data.items())]}
    fd,name=tempfile.mkstemp(dir=destination.parent,prefix='.artifact-');os.close(fd)
