import os,re,json,hashlib,tempfile,subprocess
from pathlib import Path
def stage_inputs(repo,manifest,expected_commit,destination):
    repo=Path(repo).resolve();destination=Path(destination)
    if not isinstance(expected_commit,str) or not re.fullmatch(r'[0-9a-f]{40}',expected_commit) or manifest.get('commit')!=expected_commit:raise ValueError('approved commit')
    head=subprocess.check_output(['git','-C',str(repo),'rev-parse','--verify','HEAD'],text=True).strip()
    if head!=expected_commit or subprocess.check_output(['git','-C',str(repo),'status','--porcelain','--untracked-files=all']):raise ValueError('changed or dirty source')
    if destination.exists():raise FileExistsError(destination)
    inputs=manifest.get('inputs')
    if not isinstance(inputs,list) or not inputs:raise ValueError('explicit inputs')
    files={}
    for entry in inputs:
        name=entry.get('path')
        if not isinstance(name,str) or not name or name.startswith('/') or '\\' in name or ':' in name or any(part in ('','.','..') for part in name.split('/')) or name in files:raise ValueError('relative unique input')
        path=repo
        for part in name.split('/'):
            path=path/part
            if path.is_symlink():raise ValueError('no symlink inputs')
        raw=path.read_bytes()
        if type(entry.get('bytes')) is not int or len(raw)!=entry['bytes'] or hashlib.sha256(raw).hexdigest()!=entry.get('sha256'):raise ValueError('changed input bytes')
        files[name]=raw
    with tempfile.TemporaryDirectory(dir=destination.parent,prefix='.stage-inputs-') as directory:
        stage=Path(directory)/'inputs';stage.mkdir(mode=0o700)
        for name,raw in files.items():
            path=stage/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(raw);path.chmod(0o600)
        os.rename(stage,destination)
    return expected_commit
