import sqlite3,json,hashlib,re
def apply_once(path,request_id,version,statements):
    if not isinstance(request_id,str) or not re.fullmatch(r'[a-z0-9_-]{1,40}',request_id) or type(version) is not int or version<=0 or not isinstance(statements,list) or not statements or any(not isinstance(x,str) or not x for x in statements):raise ValueError('migration identity')
    digest=hashlib.sha256(json.dumps(statements,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
    connection=sqlite3.connect(path,timeout=2,isolation_level=None)
    try:
        connection.execute('BEGIN IMMEDIATE')
        row=connection.execute('SELECT request_id,version,digest FROM migration_runs WHERE request_id=? OR version=?',(request_id,version)).fetchone()
        if row:
            if row!=(request_id,version,digest):raise ValueError('migration identity conflict')
            connection.rollback();return False
        forbidden={sqlite3.SQLITE_TRANSACTION,sqlite3.SQLITE_SAVEPOINT,sqlite3.SQLITE_ATTACH,sqlite3.SQLITE_DETACH,sqlite3.SQLITE_PRAGMA}
        connection.set_authorizer(lambda action,*args:sqlite3.SQLITE_DENY if action in forbidden else sqlite3.SQLITE_OK)
        for statement in statements:connection.execute(statement)
        connection.set_authorizer(None)
        connection.execute('INSERT INTO migration_runs VALUES(?,?,?)',(request_id,version,digest));connection.commit();return True
    except BaseException:connection.set_authorizer(None);connection.rollback();raise
    finally:connection.close()
