def run_budgeted(commands,total,per_call):
    if any(type(x) not in (int,float) or not math.isfinite(x) or not 0<x<=3 for x in (total,per_call)) or not isinstance(commands,list) or any(not isinstance(argv,list) or not argv or any(not isinstance(arg,str) for arg in argv) for argv in commands):raise ValueError('bounded commands and deadlines')
    deadline=time.monotonic()+total;codes=[]
